create table if not exists public.kd_group_settings (conversation_id uuid primary key references public.kd_conversations(id) on delete cascade, title text not null, description text default '', avatar_url text, invite_token uuid not null default gen_random_uuid(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists kd_group_settings_invite_token_idx on public.kd_group_settings(invite_token);
create table if not exists public.kd_group_invites (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.kd_conversations(id) on delete cascade, inviter_id uuid not null references auth.users(id) on delete cascade, invitee_id uuid references auth.users(id) on delete cascade, token uuid not null default gen_random_uuid(), status text not null default 'pending' check(status in ('pending','accepted','revoked')), created_at timestamptz not null default now(), unique(conversation_id,token));
create index if not exists kd_group_invites_invitee_idx on public.kd_group_invites(invitee_id,status);
create index if not exists kd_group_members_role_idx on public.kd_conversation_members(conversation_id,role);
alter table public.kd_group_settings enable row level security;
alter table public.kd_group_invites enable row level security;
drop policy if exists kd_group_settings_select on public.kd_group_settings;
create policy kd_group_settings_select on public.kd_group_settings for select using (exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_settings.conversation_id and m.user_id=auth.uid()));
drop policy if exists kd_group_settings_insert on public.kd_group_settings;
create policy kd_group_settings_insert on public.kd_group_settings for insert with check (exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_settings.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists kd_group_settings_update on public.kd_group_settings;
create policy kd_group_settings_update on public.kd_group_settings for update using (exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_settings.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin'))) with check (exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_settings.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists kd_group_invites_select on public.kd_group_invites;
create policy kd_group_invites_select on public.kd_group_invites for select using (inviter_id=auth.uid() or invitee_id=auth.uid() or exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_invites.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists kd_group_invites_insert on public.kd_group_invites;
create policy kd_group_invites_insert on public.kd_group_invites for insert with check (inviter_id=auth.uid() and exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_invites.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
drop policy if exists kd_group_invites_update on public.kd_group_invites;
create policy kd_group_invites_update on public.kd_group_invites for update using (inviter_id=auth.uid() or invitee_id=auth.uid() or exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_invites.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin'))) with check (inviter_id=auth.uid() or invitee_id=auth.uid() or exists(select 1 from public.kd_conversation_members m where m.conversation_id=kd_group_invites.conversation_id and m.user_id=auth.uid() and m.role in ('owner','admin')));
create or replace function public.kd_create_group(p_title text,p_description text default '') returns uuid language plpgsql security invoker set search_path=public as $$ declare c uuid; begin if auth.uid() is null then raise exception 'not authenticated'; end if; if length(trim(coalesce(p_title,'')))<1 then raise exception 'group title required'; end if; insert into kd_conversations(kind,created_by) values('group',auth.uid()) returning id into c; insert into kd_conversation_members(conversation_id,user_id,role) values(c,auth.uid(),'owner'); insert into kd_group_settings(conversation_id,title,description) values(c,trim(p_title),coalesce(trim(p_description),'')); return c; end $$;
grant execute on function public.kd_create_group(text,text) to authenticated;
